<script setup lang="ts">
import {onMounted,reactive,ref} from "vue";import{http}from"@/utils/http";import{message}from"@/utils/message";
const rows=ref<any[]>([]),loading=ref(false),supplier=ref<number>(),price=ref(0),expectedDate=ref(""),suppliers=ref<any[]>([]),convertRow=ref<any>(),convertVisible=ref(false);
const tagType=(status:number)=>(["info","warning","success","danger","info"][status]??"info") as any;
async function load(){loading.value=true;try{const r:any=await http.request("get","/purchase-requisition",{params:{page:1,pageSize:100}});if(r.code===0)rows.value=r.data?.list??[];else message(r.message,{type:"error"})}catch(e:any){message(e?.message||"加载申请失败",{type:"error"})}finally{loading.value=false}}
async function shortages(){try{const r:any=await http.request("post","/purchase-requisition/shortages");if(r.code===0){message(r.message,{type:"success"});load()}else message(r.message,{type:"warning"})}catch(e:any){message(e?.message||"生成申请失败",{type:"error"})}}
async function act(row:any,action:string,body?:any){try{const r:any=await http.request("post",`/purchase-requisition/${row.id}/${action}`,{data:body});if(r.code===0){message(r.message,{type:"success"});load()}else message(r.message,{type:"error"})}catch(e:any){message(e?.message||"操作失败",{type:"error"})}}
async function beginConvert(row:any){convertRow.value=row;try{const r:any=await http.request("get","/supplier/options");suppliers.value=r.data??[]}catch{}convertVisible.value=true}
function convert(){if(!supplier.value){message("请选择供应商",{type:"warning"});return}act(convertRow.value,"convert",{supplierId:supplier.value,expectedDate:expectedDate.value||null,price:Number(price.value)||0}).then(()=>{convertVisible.value=false})}
onMounted(load);
</script>
<template><el-card shadow="never"><div class="toolbar"><strong>采购申请 / 审批</strong><el-button type="primary" @click="shortages">按工单短缺生成申请</el-button></div><el-table v-loading="loading" :data="rows" border stripe><el-table-column prop="code" label="申请编号" width="180"/><el-table-column prop="requestDate" label="申请日期" width="130"><template #default="{row}">{{String(row.requestDate||"").slice(0,10)}}</template></el-table-column><el-table-column prop="totalQty" label="申请数量" width="120"/><el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="tagType(row.approvalStatus)">{{["草稿","待审批","已批准","已驳回","已关闭"][row.approvalStatus]??"未知"}}</el-tag></template></el-table-column><el-table-column prop="approvalRemark" label="审批意见" min-width="160"/><el-table-column label="操作" width="270" fixed="right"><template #default="{row}"><el-button v-if="row.approvalStatus===0" link type="primary" @click="act(row,'submit')">提交审批</el-button><template v-if="row.approvalStatus===1"><el-button link type="success" @click="act(row,'approve',null)">批准</el-button><el-button link type="danger" @click="act(row,'reject','不予批准')">驳回</el-button></template><el-button v-if="row.approvalStatus===2" link type="primary" @click="beginConvert(row)">转采购订单</el-button></template></el-table-column></el-table><el-alert style="margin-top:14px" type="info" :closable="false" title="短缺申请来源于工单物料需求，生成时扣除现有库存和已有未转采购量，审批通过后保留申请行到采购订单行映射。"/></el-card><el-dialog v-model="convertVisible" title="批准申请转采购订单" width="520px"><el-form label-width="100px"><el-form-item label="供应商" required><el-select v-model="supplier" filterable style="width:100%"><el-option v-for="s in suppliers" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="预计到货"><el-date-picker v-model="expectedDate" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item><el-form-item label="参考单价"><el-input-number v-model="price" :min="0" :precision="2"/></el-form-item></el-form><template #footer><el-button @click="convertVisible=false">取消</el-button><el-button type="primary" @click="convert">生成草稿采购订单</el-button></template></el-dialog></template>
<style scoped>.toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}</style>
